    const SCALE: *const f32 = (crate::win::EXPECTED_IMAGE_BASE + 0x8e_26dc) as *const f32;
    const BIAS: *const f32 = (crate::win::EXPECTED_IMAGE_BASE + 0x40_29d0) as *const f32;
