    let origin_x_ptr = unsafe { chunk.add(0x108) };
    // SAFETY: `origin_x_ptr` addresses the readable grid-origin x float.
    let origin_x = unsafe { origin_x_ptr.cast::<f32>().read() };
    // SAFETY: `chunk+0x10c` is the aligned grid-origin y float.
    let origin_y_ptr = unsafe { chunk.add(0x10c) };
    // SAFETY: `origin_y_ptr` addresses the readable grid-origin y float.
    let origin_y = unsafe { origin_y_ptr.cast::<f32>().read() };
    // SAFETY: `chunk+0x100` is the aligned grid x dim.
    let dim_x_ptr = unsafe { chunk.add(0x100) };
    // SAFETY: `dim_x_ptr` addresses the readable grid x dim.
    let dim_x = unsafe { dim_x_ptr.cast::<i32>().read() };
    // SAFETY: `chunk+0x104` is the aligned grid y dim.
    let dim_y_ptr = unsafe { chunk.add(0x104) };
