    let ea = unsafe { elem_base.add(index_a as usize * 0x40) };
    // SAFETY: each index*0x40 is an in-bounds 0x40-byte element (caller-validated).
    let eb = unsafe { elem_base.add(index_b as usize * 0x40) };

