/// Live-particle count for the current emitter draw (`0xcf5b60`).
///
/// Set by `CParticleEmitter::Render` to `min(0x4000 / vertsPerQuad, this+0x64)`.
const PQ_LIVE_COUNT: *const u32 = (crate::win::EXPECTED_IMAGE_BASE + 0x8f_5b60) as *const u32;
/// Depth-sort view rows for the view-space Z dot (`0xcf5b70/80/90`, `+0xa0` constant).
///
/// Written per frame by the render setup.
const PQ_VIEW_R0: *const f32 = (crate::win::EXPECTED_IMAGE_BASE + 0x8f_5b70) as *const f32;
const PQ_VIEW_R1: *const f32 = (crate::win::EXPECTED_IMAGE_BASE + 0x8f_5b80) as *const f32;
const PQ_VIEW_R2: *const f32 = (crate::win::EXPECTED_IMAGE_BASE + 0x8f_5b90) as *const f32;
const PQ_VIEW_R3: *const f32 = (crate::win::EXPECTED_IMAGE_BASE + 0x8f_5ba0) as *const f32;
/// Depth-sort scratch heap.
///
/// Control block (`0xcf58c8`), data-base pointer field (`+0xc` = `0xcf58d4`), element count
/// (`+0x1c` = `0xcf58e4`). Each element is 8 bytes: `{ viewZ: f32, particle_ptr: u32 }`. The vector
/// grows via the stock grow helper; the base pointer is re-read live because a grow may relocate
/// it.
const PQ_HEAP_CTRL: *mut u8 = (crate::win::EXPECTED_IMAGE_BASE + 0x8f_58c8) as *mut u8;
const PQ_HEAP_DATA: *const *mut u8 =
    (crate::win::EXPECTED_IMAGE_BASE + 0x8f_58d4) as *const *mut u8;
const PQ_HEAP_COUNT: *mut u32 = (crate::win::EXPECTED_IMAGE_BASE + 0x8f_58e4) as *mut u32;

/// Resolve a live particle record pointer.
///
/// `(*(this+0x5c))[idx] << shift + base`, where `(shift, base)` is `(5, this+0x3c)` or
/// `(6, this+0x4c)` selected by `this+0x28` (the per-record stride class).
///
/// SAFETY: `this+0x5c` is the in-bounds index-array pointer and `idx` is within
/// the live-particle range the caller iterates.
unsafe fn pq_particle_ptr(inst: *const u8, idx: usize) -> *mut f32 {
    // SAFETY: `this+0x5c` is the index-array pointer.
    let arr = unsafe { anim_u32(inst, 0x5c) } as *const u8;
    // SAFETY: `arr[idx]` (byte idx*4) is in-bounds of the index array.
    let raw = unsafe { anim_u32(arr, idx * 4) };
    // SAFETY: `this+0x28` selects the per-record stride class.
    let (shift, base_off) = if unsafe { anim_u32(inst, 0x28) } == 0 {
        (5u32, 0x3c)
    } else {
        (6u32, 0x4c)
    };
    // SAFETY: `this + base_off` is the in-bounds record-array base.
    let base = unsafe { anim_u32(inst, base_off) };
    raw.wrapping_shl(shift).wrapping_add(base) as *mut f32
}

/// Read element `idx`'s view-Z from the depth-sort heap (base re-read live).
///
/// SAFETY: `idx` is within the live heap extent.
unsafe fn pq_heap_z(idx: usize) -> f32 {
    // SAFETY: the data-base pointer field is live.
    let base = unsafe { PQ_HEAP_DATA.read() };
    // SAFETY: element `idx`'s `.z` is the dword at byte `idx*8`.
    f32::from_bits(unsafe { anim_u32(base, idx * 8) })
}

/// Read element `idx`'s particle pointer from the depth-sort heap.
///
/// SAFETY: `idx` is within the live heap extent.
unsafe fn pq_heap_ptr(idx: usize) -> u32 {
    // SAFETY: the data-base pointer field is live.
    let base = unsafe { PQ_HEAP_DATA.read() };
    // SAFETY: element `idx`'s `.ptr` is the dword at byte `idx*8+4`.
    unsafe { anim_u32(base, idx * 8 + 4) }
}

/// Write `{ z, ptr }` into heap element `idx`.
///
/// SAFETY: `idx` is within the reserved heap extent.
unsafe fn pq_heap_set(idx: usize, z: f32, ptr: u32) {
    // SAFETY: the data-base pointer field is live.
    let base = unsafe { PQ_HEAP_DATA.read() };
    // SAFETY: element `idx`'s `.z` dword is writable.
    unsafe { anim_put_u32(base, idx * 8, z.to_bits()) };
    // SAFETY: element `idx`'s `.ptr` dword is writable.
    unsafe { anim_put_u32(base, idx * 8 + 4, ptr) };
}

/// Reserve one slot at the end of the depth-sort vector.
///
/// The stock fast path at `0x7b63a0` (`ctrl, null, 1`). Bumps the count; only the rare
/// capacity-exhausted case calls the stock grow helper at `0x7bff20`, so the steady-state path
/// is call-free.
///
/// SAFETY: `PQ_HEAP_CTRL` is the live vector control block.
unsafe fn pq_heap_reserve_one() {
    let ctrl = PQ_HEAP_CTRL;
    // SAFETY: `ctrl+0x1c` is the in-bounds element-count field.
    let count = unsafe { anim_u32(ctrl, 0x1c) };
    // SAFETY: `ctrl+0x18` is the in-bounds capacity field.
    let cap = unsafe { anim_u32(ctrl, 0x18) };
    if cap < count + 1 {
        // SAFETY: `ctrl+0x14` is the minimum-growth field.
        let min_grow = unsafe { anim_u32(ctrl, 0x14) };
        if min_grow == 0 {
            return;
        }
        let mut grow = (count - cap) + 1;
        if grow < min_grow {
            grow = min_grow;
        }
        // The stock vector grow: `__thiscall(ctrl, newCapacityBytes, 1) -> bool`.
        type GrowVecFn = extern "thiscall" fn(*mut u8, u32, u8) -> u8;
        const GROW_VA: usize = crate::win::EXPECTED_IMAGE_BASE + 0x3b_ff20;
        // SAFETY: `GROW_VA` is the stock grow helper at a fixed image offset; the
        // transmuted signature matches its declared `__thiscall` prototype.
        let growfn: GrowVecFn = unsafe { core::mem::transmute(GROW_VA) };
        if growfn(ctrl, (cap + grow).wrapping_mul(8), 1) == 0 {
            return;
        }
        // SAFETY: `ctrl+0x18` is the writable capacity field.
        unsafe { anim_put_u32(ctrl, 0x18, cap + grow) };
    }
    // SAFETY: `ctrl+0x1c` is the writable count field.
    unsafe { anim_put_u32(ctrl, 0x1c, count + 1) };
}

/// `CParticleEmitter::RenderParticles` — `__thiscall(ecx = this, stack = vertexStream)`.
///
/// Per-emitter draw driver: emits each live particle's quad into the `GxVertexCursor` via
/// [`c_particle_emitter__build_particle_quad__7b2a50`] (called by name so LLVM inlines the whole
/// per-particle path). With sort flag `0x10` clear, emits in array order; with it set, builds a
/// binary max-heap on each particle's view-space Z and emits far-to-near. Finally stores the
/// emitted-quad count (`vertexStream[8] / *(this+0x9c)`) at `this+0x1c`.
// The heap sift negates `>=` to keep the stock polarity, so an unordered
// view-space Z sifts the way it did; the plain `<` rewrite would swap it.
