    const IN_AREAS_VA: usize = EXPECTED_IMAGE_BASE + 0x29_b520;
    // SAFETY: 0x69b520 is `__fastcall(ecx = this, edx = flags_out, stack = height_io,
    // surface_vec3_out) -> u8`, `ret 8`. The stock driver passes all four (pushing
    // surface_vec3_out then height_io at 0x69b6e2/0x69b6e5, with `this`/`flags_out`
    // still live in ecx/edx). Calling it with fewer args leaves the stack imbalanced
    // by the callee's `ret 8`. Signature transmute of a fixed code VA in the
    // non-DYNAMICBASE host image.
    let in_areas: extern "fastcall" fn(*mut core::ffi::c_void, *mut u32, *mut f32, *mut f32) -> u8 =
        unsafe { core::mem::transmute(IN_AREAS_VA) };
