    let origin = unsafe { ORIGIN.read() };
    // SAFETY: fixed, initialized `.data` dword.
    let scale = unsafe { SCALE.read() };
    // SAFETY: fixed, initialized `.data` dword.
    let bias = unsafe { BIAS.read() };
    // SAFETY: fixed, initialized `.rdata` dword (0.009999999776).
    let epsilon = unsafe { EPSILON.read() };
    // SAFETY: fixed, initialized `.rdata` dword (0.5).
    let half = unsafe { HALF.read() };

    let g = crate::math::world::c_world__query_liquid_grid_map__69b6d0(px, py, origin, scale, bias);

    // --- Grid double-indirection: chunk row, sub pointer, face-table head.
    const GRID: *const *const u8 = (EXPECTED_IMAGE_BASE + 0x89_6318) as *const *const u8;
    // SAFETY: the kernel builds `grid_index` as `((ix>>7)&0x3f)<<6 | ((iy>>7)&0x3f)`,
    // so it is <= 4095 — in bounds for the 64x64 chunk-pointer table at 0xc96318.
