// --- Small strided-field helpers for the driver above (file-local). ---

/// Read a `u32` at `base + off`.
#[inline]
unsafe fn rd_u32(base: *const u8, off: usize) -> u32 {
    // SAFETY: caller guarantees `base + off` is in-bounds.
    let p = unsafe { base.add(off) };
    // SAFETY: the slot is an aligned, initialized dword per the contract.
    unsafe { p.cast::<u32>().read() }
}

/// Read a `*const u8` (pointer-sized field) at `base + off`.
#[inline]
unsafe fn rd_ptr(base: *const u8, off: usize) -> *const u8 {
    // SAFETY: caller guarantees `base + off` is in-bounds.
    let p = unsafe { base.add(off) };
    // SAFETY: the slot is an aligned, initialized pointer per the contract.
    unsafe { p.cast::<*const u8>().read() }
}

/// Read an `f32` at `base + off`.
#[inline]
unsafe fn rd_f32(base: *const u8, off: usize) -> f32 {
    // SAFETY: caller guarantees `base + off` is in-bounds.
    let p = unsafe { base.add(off) };
    // SAFETY: the slot is an aligned, initialized f32 per the contract.
    unsafe { p.cast::<f32>().read() }
}

/// Write a `u32` at `base + off`.
#[inline]
unsafe fn wr_u32(base: *mut u8, off: usize, v: u32) {
    // SAFETY: caller guarantees `base + off` is in-bounds.
    let p = unsafe { base.add(off) };
    // SAFETY: the slot is an aligned, writable dword per the contract.
    unsafe { p.cast::<u32>().write(v) };
}

// Dense per-tile geometry collector: an impure driver whose float-heavy
