/// render-queue draw-batch sort comparator (a qsort/sort predicate, also reached
/// by VA from `bdl_draw_list_equal` above): resolves the two 0x40-stride
/// elements at `*(mgr+0x34) + idx*0x40` (record pointer at `E+4`) and walks a
/// strict key cascade, first unequal key deciding -1/+1, all-equal returning 0:
///
/// 1. u32 `rec+0x30` (record order key — a pointer value compared unsigned);
/// 2. u32 `E+0x1c` (element secondary key — the ELEMENT, not the record);
/// 3. only when the shader pointers `S = *(rec+0x3b8)` DIFFER (identity check):
///    f32 `S+0x184` then `S+0x188` (plain ordered `<` in both directions —
///    equal or NaN falls through, matching stock's `FCOMP; FNSTSW;
///    TEST AH,0x5; JP` / `TEST AH,0x41; JNZ` polarity), then memcmp blocks
///    `S+0x190` (12B), `S+0x84`, `S+0xa8`, `S+0xcc` (36B each);
/// 4. k-indexed 0x50-stride table block, A-side asymmetry kept exactly as
///    stock: `k = *(u16*)(*(Ea+0x2c)+8)` (A element) guarded unsigned against
///    `bound = *(u32*)(*(*(recA+0x30)+0x130)+0x54)` (A record); only when
///    `k < bound`: memcmp 12B at `*(rec+0xa0) + 0xc + k*0x50` on both sides;
/// 5. memcmp 12B `rec+0x1a0`;
/// 6. memcmp 12B `rec+0x1ac` (final).
///
/// All memcmps are unsigned lexicographic (`crate::math::gx::lex_cmp`, the
/// `REPE CMPSB; SBB; SBB` idiom). Stock is a self-contained leaf (zero
/// callees), and this port is a pure reader — no writes, no call-outs — so the
/// differential double-run is side-effect free. The unguarded deref chain
/// (`rec`, `S`, `E+0x2c`, `rec+0x30→+0x130`) is transcribed exactly; the
/// comparator only runs over live queue elements, the same liveness assumption
/// stock makes.
pub fn render_batch__compare_sort_key__70a710(idx_a: i32, idx_b: i32, mgr: *mut u8) -> i32 {
    /// Read a pointer field at `p + off`.
    ///
    /// Unaligned-tolerant, like every game-struct read in this module.
    #[inline]
    unsafe fn rdp(p: *const u8, off: usize) -> *const u8 {
        // SAFETY: caller guarantees `p + off` is an in-bounds pointer field.
        let q = unsafe { p.add(off) };
        // SAFETY: as above.
        unsafe { q.cast::<*const u8>().read_unaligned() }
    }
    /// Read a `u32` field at `p + off`.
    #[inline]
    unsafe fn rd32(p: *const u8, off: usize) -> u32 {
        // SAFETY: caller guarantees `p + off` is an in-bounds dword field.
        let q = unsafe { p.add(off) };
        // SAFETY: as above.
        unsafe { q.cast::<u32>().read_unaligned() }
    }
    /// Read a zero-extended `u16` field at `p + off` (stock `MOVZX`).
    #[inline]
    unsafe fn rd16(p: *const u8, off: usize) -> u32 {
        // SAFETY: caller guarantees `p + off` is an in-bounds word field.
        let q = unsafe { p.add(off) };
        // SAFETY: as above.
        u32::from(unsafe { q.cast::<u16>().read_unaligned() })
    }
    /// Read an `f32` field at `p + off`.
    #[inline]
    unsafe fn rdf(p: *const u8, off: usize) -> f32 {
        // SAFETY: caller guarantees `p + off` is an in-bounds f32 field.
        let q = unsafe { p.add(off) };
        // SAFETY: as above.
        unsafe { q.cast::<f32>().read_unaligned() }
    }

    // SAFETY: `mgr` is the live sort manager; `+0x34` holds the element-array
    // base (stock reads it unconditionally, 0x70a716).
    let base = unsafe { rdp(mgr.cast_const(), 0x34) };
    // `base + idx*0x40`: stock `SHL idx,6; ADD base` — 32-bit wraparound address
    // math, reproduced bit-exactly by `wrapping_add` on the 32-bit target.
    let ea = base.wrapping_add((idx_a as usize) << 6);
    let eb = base.wrapping_add((idx_b as usize) << 6);
    // SAFETY: `E+4` is the element's record pointer (read unconditionally).
    let rec_a = unsafe { rdp(ea, 0x4) };
    // SAFETY: as above for the B-side element.
    let rec_b = unsafe { rdp(eb, 0x4) };

    // (1) u32 record order key.
    // SAFETY: `rec+0x30` is an in-bounds record field.
    let ka = unsafe { rd32(rec_a, 0x30) };
    // SAFETY: as above, B side.
    let kb = unsafe { rd32(rec_b, 0x30) };
    if ka < kb {
        return -1;
    }
    if kb < ka {
        return 1;
    }

    // (2) u32 element secondary key — read from the ELEMENTS, not the records.
    // SAFETY: `E+0x1c` is an in-bounds element field.
    let ka = unsafe { rd32(ea, 0x1c) };
    // SAFETY: as above, B side.
    let kb = unsafe { rd32(eb, 0x1c) };
    if ka < kb {
        return -1;
    }
    if kb < ka {
        return 1;
    }

    // (3) shader-block cascade, only when the shader pointers differ (stock
    // `CMP EDX,EBX; JZ 0x70a915` skips the whole block on identity).
    // SAFETY: `rec+0x3b8` is the record's shader pointer.
    let sa = unsafe { rdp(rec_a, 0x3b8) };
    // SAFETY: as above, B side.
    let sb = unsafe { rdp(rec_b, 0x3b8) };
    if sa != sb {
        for off in [0x184usize, 0x188] {
            // SAFETY: `S+off` is an in-bounds f32 shader key.
            let fa = unsafe { rdf(sa, off) };
            // SAFETY: as above, B side.
            let fb = unsafe { rdf(sb, off) };
            // Plain ordered `<` both directions: equal or NaN falls through to
            // the next key — exactly stock's x87 unordered-compare polarity.
            if fa < fb {
                return -1;
            }
            if fb < fa {
                return 1;
            }
        }
        for (off, len) in [(0x190usize, 12usize), (0x84, 36), (0xa8, 36), (0xcc, 36)] {
            // SAFETY: `S+off` starts a `len`-byte in-bounds key block.
            let pa = unsafe { sa.add(off) };
            // SAFETY: as above, B side.
            let pb = unsafe { sb.add(off) };
            // SAFETY: both blocks address `len` readable key bytes.
            let c = unsafe { crate::math::gx::lex_cmp(pa, pb, len) };
            if c != 0 {
                return c;
            }
        }
    }

    // (4) k-indexed 0x50-stride table block: index from the A-side ELEMENT,
    // bound from the A-side RECORD — stock's asymmetry, kept verbatim.
    // SAFETY: `Ea+0x2c` is the element's key-source object pointer.
    let ko = unsafe { rdp(ea, 0x2c) };
    // SAFETY: `+8` is that object's u16 table index.
    let k = unsafe { rd16(ko, 0x8) };
    // SAFETY: `recA+0x30` (compared as a key above) is dereferenced here, as in
    // stock (0x70a91c).
    let m30 = unsafe { rdp(rec_a, 0x30) };
    // SAFETY: `+0x130` is a nested object pointer.
    let mtab = unsafe { rdp(m30, 0x130) };
    // SAFETY: `+0x54` is the u32 entry count bounding `k`.
    let bound = unsafe { rd32(mtab, 0x54) };
    if k < bound {
        let off = k as usize * 0x50 + 0xc;
        // SAFETY: `recA+0xa0` is the 0x50-stride table base pointer.
        let ta = unsafe { rdp(rec_a, 0xa0) };
        // SAFETY: as above, B side.
        let tb = unsafe { rdp(rec_b, 0xa0) };
        // SAFETY: `table + 0xc + k*0x50` is the in-bounds entry block
        // (`k < bound` just checked, exactly the stock guard).
        let pa = unsafe { ta.add(off) };
        // SAFETY: as above, B side.
        let pb = unsafe { tb.add(off) };
        // SAFETY: both blocks address 12 readable key bytes.
        let c = unsafe { crate::math::gx::lex_cmp(pa, pb, 12) };
        if c != 0 {
            return c;
        }
    }

    // (5) record key block `rec+0x1a0` (12B).
    // SAFETY: `rec+0x1a0` starts a 12-byte in-bounds key block.
    let pa = unsafe { rec_a.add(0x1a0) };
    // SAFETY: as above, B side.
    let pb = unsafe { rec_b.add(0x1a0) };
    // SAFETY: both blocks address 12 readable key bytes.
    let c = unsafe { crate::math::gx::lex_cmp(pa, pb, 12) };
    if c != 0 {
        return c;
    }

    // (6) final record key block `rec+0x1ac` (12B) decides -1/0/1.
    // SAFETY: `rec+0x1ac` starts a 12-byte in-bounds key block.
    let pa = unsafe { rec_a.add(0x1ac) };
    // SAFETY: as above, B side.
    let pb = unsafe { rec_b.add(0x1ac) };
    // SAFETY: both blocks address 12 readable key bytes.
    unsafe { crate::math::gx::lex_cmp(pa, pb, 12) }
}

/// `World_RasterizeTraceLineCells`.
///
/// `__fastcall(ecx = p1: *const f32 {x0,y0}, edx = p2: *const f32 {x1,y1},
/// stack = desc: *const i32 {start major, start perp, end major, end perp})`,
/// `RET 0x4`, void. DDA-rasterizes the 2D segment `p1 -> p2` into the GLOBAL
/// grid-cell pair list (the walk itself lives in
/// `math::world::world_rasterize_trace_line_cells__69c780`): each emitted
/// `(perp, major)` i32 pair is appended at the list base held at `0xc962c8`
/// through the global write cursor at `0xc89f40`. The cursor counts DWORDS,
/// not pairs — every store addresses `[base + cursor*4]` and bumps the cursor
/// by one (`INC` per dword store, 0x69c7ee–0x69c7fa), two bumps per pair.
/// Stock performs NO bounds check on the list; the raw cursor bump is
/// reproduced exactly (raw pointer + wrapping offset, never a slice — the
/// buffer's sizing is the caller's contract). Zero callees; the four module
/// f32 constants and both list globals are read live from the host image.
pub fn world_rasterize_trace_line_cells__69c780(p1: *const f32, p2: *const f32, desc: *const i32) {
    if p1.is_null() || p2.is_null() || desc.is_null() {
        return;
    }
    const BASE: usize = crate::win::EXPECTED_IMAGE_BASE;
    // Module f32 constants (rva = VA − 0x400000): slope-reciprocal numerator
    // (VA 0x7ff9d8), grid step (0x810678), axis scale (0x8107a4), and the bias
    // subtracted before the FISTP (0x86a758).
    const NUMER: *const f32 = (BASE + 0x3f_f9d8) as *const f32;
    const STEP: *const f32 = (BASE + 0x41_0678) as *const f32;
    const SCALE: *const f32 = (BASE + 0x41_07a4) as *const f32;
    const BIAS: *const f32 = (BASE + 0x46_a758) as *const f32;
    // Global output list: dword write cursor (VA 0xc89f40) and the base pointer
    // the game stores at VA 0xc962c8.
    const CURSOR: *mut i32 = (BASE + 0x88_9f40) as *mut i32;
    const LIST: *const *mut i32 = (BASE + 0x89_62c8) as *const *mut i32;

    // SAFETY: `p1` is the non-null caller-owned segment start (two packed f32);
    // game data is 2-byte aligned -> read unaligned.
    let a = unsafe { p1.cast::<[f32; 2]>().read_unaligned() };
    // SAFETY: as above, for the non-null segment end `p2`.
    let b = unsafe { p2.cast::<[f32; 2]>().read_unaligned() };
    // SAFETY: `desc` is the non-null caller-owned 4-i32 cell descriptor.
    let d = unsafe { desc.cast::<[i32; 4]>().read_unaligned() };
    // SAFETY: fixed engine f32 global in the live host image (base verified at
    // load); read by value.
    let numer = unsafe { NUMER.read() };
    // SAFETY: as above.
    let step = unsafe { STEP.read() };
    // SAFETY: as above.
    let scale = unsafe { SCALE.read() };
    // SAFETY: as above.
    let bias = unsafe { BIAS.read() };
    crate::math::world::world_rasterize_trace_line_cells__69c780(
        a,
        b,
        d,
        numer,
        step,
        scale,
        bias,
        |first, second| {
            for v in [first, second] {
                // SAFETY: the global dword write cursor at fixed VA 0xc89f40.
                let c = unsafe { CURSOR.read() };
                // SAFETY: as above; stock-faithful raw bump (wrapping, and with
                // no bounds check, exactly like the original's INC).
                unsafe { CURSOR.write(c.wrapping_add(1)) };
                // SAFETY: the global list-base pointer at fixed VA 0xc962c8.
                let list = unsafe { LIST.read() };
                // SAFETY: appends at `list[cursor]` exactly as stock — the
                // caller sizes the buffer, no added guard; raw wrapping offset
                // (never a slice) + unaligned store for game memory.
                unsafe { list.wrapping_offset(c as isize).write_unaligned(v) };
            }
        },
    );
}

/// `World_TraceLineAgainstTerrain` — the terrain trace-line entry point.
///
/// `fastcall(ecx = startPos f32*[2..], edx = endPos f32*[2..];
/// inoutHitFraction f32*, flags, outHitChunk i32*)`, `RET 0xC`, void. Sets up
/// the world→grid recentre and cell indices, resets the trace cursor,
/// dispatches to one of four DDA span walkers by the major-axis /
/// same-row-or-column tests, then runs the chunk worker.
///
/// Two of the four walkers are OURS (the X-major cell rasterizer 0x69c780
/// and the Y-major sloped DDA 0x69c600) — called directly; the two
/// degenerate span emitters (0x69c570 same-row / 0x69c4e0 same-column) and
/// the pointer-chasing chunk worker (0x69c920, NO-GO) stay delegates. NaN
/// branch polarities pinned: an unordered `absDy` takes the
/// same-row path, an unordered `absDx` the same-column path, and an
/// unordered major-axis compare routes to the X-major cell walker.
// The two degenerate-span gates and the major-axis compare are negated, which is
// what routes the unordered cases to the paths the doc above names; the un-negated
// `<` / `<=` rewrite would send them elsewhere.
#[allow(clippy::neg_cmp_op_on_partial_ord)]
pub fn world_trace_line_against_terrain__69c320(
    start_pos: *const f32,
    end_pos: *const f32,
    inout_hit_fraction: *mut f32,
    flags: u32,
    out_hit_chunk: *mut i32,
) {
    const BASE: usize = crate::win::EXPECTED_IMAGE_BASE;
    // SAFETY: fixed `.rdata`/`.data` grid constants in the live host image.
    let center = unsafe { ((BASE + 0x3f_fab4) as *const f32).read() };
    // SAFETY: grid scale.
    let scale = unsafe { ((BASE + 0x41_07a4) as *const f32).read() };
    // SAFETY: cell bias.
    let bias = unsafe { ((BASE + 0x46_a758) as *const f32).read() };
    // SAFETY: near-zero epsilon.
    let eps = unsafe { ((BASE + 0x40_29d4) as *const f32).read() };

    // SAFETY: startPos/endPos each address at least 2 f32 (x, y).
    let sx0 = unsafe { start_pos.read_unaligned() };
    // SAFETY: startPos[1].
    let sy0 = unsafe { start_pos.wrapping_add(1).read_unaligned() };
    // SAFETY: endPos[0].
    let ex0 = unsafe { end_pos.read_unaligned() };
    // SAFETY: endPos[1].
    let ey0 = unsafe { end_pos.wrapping_add(1).read_unaligned() };

    use crate::math::world as w;
    let rsy = w::terrain_recentre__69c320(sy0, center);
    let rsx = w::terrain_recentre__69c320(sx0, center);
    let rey = w::terrain_recentre__69c320(ey0, center);
    let rex = w::terrain_recentre__69c320(ex0, center);
    let dy = w::terrain_delta__69c320(rey, rsy);
    let dx = w::terrain_delta__69c320(rex, rsx);
    let ey_cell = w::terrain_cell__69c320(scale, rey, bias);
    let ex_cell = w::terrain_cell__69c320(scale, rex, bias);
    let sy_cell = w::terrain_cell__69c320(scale, rsy, bias);
    let sx_cell = w::terrain_cell__69c320(scale, rsx, bias);
    let abs_dy = dy.abs();
    let abs_dx = dx.abs();

    // Cursor reset before dispatch.
    // SAFETY: fixed trace-cursor global.
    unsafe { ((BASE + 0x88_9f40) as *mut u32).write(0) };

    // Cell descriptor [sx, sy, ex, ey] shared by every walker.
    let desc: [i32; 4] = [sx_cell, sy_cell, ex_cell, ey_cell];

    // Delegates: 0x69c570 same-row span, 0x69c4e0 same-column span (both
    // thiscall(&desc), RET 0), 0x69c920 chunk worker (fastcall, RET 0xC).
    const SAME_ROW_VA: usize = BASE + 0x29_c570;
    // SAFETY: image base verified at load; signature matches the callee.
    let same_row: extern "thiscall" fn(*const i32) -> u32 =
        unsafe { core::mem::transmute(SAME_ROW_VA) };
    const SAME_COL_VA: usize = BASE + 0x29_c4e0;
    // SAFETY: image base verified at load; signature matches the callee.
    let same_col: extern "thiscall" fn(*const i32) -> u32 =
        unsafe { core::mem::transmute(SAME_COL_VA) };

    if !(abs_dy >= eps) || sy_cell == ey_cell {
        // absDy < eps / NaN, or same grid row → degenerate row span.
        same_row(desc.as_ptr());
    } else if !(abs_dx >= eps) || sx_cell == ex_cell {
        // absDx < eps / NaN, or same grid column → degenerate column span.
        same_col(desc.as_ptr());
    } else {
        // Both axes significant: p0 = [sy, sx, 0], p1 = [ey, ex, 0].
        let p0: [f32; 3] = [rsy, rsx, 0.0];
        let p1: [f32; 3] = [rey, rex, 0.0];
        if !(abs_dy > abs_dx) {
            // |dy| <= |dx| or unordered → X-major cell rasterizer (ours).
            world_rasterize_trace_line_cells__69c780(p0.as_ptr(), p1.as_ptr(), desc.as_ptr());
        } else {
            // |dy| > |dx| → Y-major sloped DDA (ours).
            rasterizer_emit_sloped_line_dda__69c600(p0.as_ptr(), p1.as_ptr(), desc.as_ptr());
        }
    }

    // 0x69c920 chunk worker — fastcall(startPos, endPos; inoutHitFraction,
    // flags, outHitChunk), RET 0xC. Pointer-chasing cell walk, NO-GO.
    const CHUNK_WORKER_VA: usize = BASE + 0x29_c920;
    // SAFETY: image base verified at load; signature matches the callee.
    let chunk_worker: extern "fastcall" fn(*const f32, *const f32, *mut f32, u32, *mut i32) -> u32 =
        unsafe { core::mem::transmute(CHUNK_WORKER_VA) };
    chunk_worker(start_pos, end_pos, inout_hit_fraction, flags, out_hit_chunk);
}

/// `Rasterizer_EmitSlopedLineDDA` — the sloped-span DDA emitter.
///
/// `__fastcall(ecx = p0: *const f32 {x0,y0}, edx = p1: *const f32 {x1,y1},
