/// Bit-faithful body of stock `TSLink__Unlink` 0x687260.
///
/// The same sequence appears three ways inside `WorldScene__CullAndBucketNodes`
/// 0x6834e0 — stock's inlined copy (0x6835b0-0x6835e1), the
/// `TSLink__ResolveLinkPtr(link, -1)` + fix-up run (0x683626-0x683641), and two
/// direct `CALL 0x687260` sites — and all three collapse here (the arithmetic
/// was cross-checked instruction-by-instruction against each). `link[0]` = next
/// node ptr; `link[1]` = prev encoding: odd or null tags a direct slot
/// (`prev & !1`), otherwise the predecessor's forward slot is
/// `link + (prev − *(next+4))` in plain integer arithmetic (offset-based
/// `TSLink` — never `ptr::add`). No-op when `link[0]` is 0; every deref stock
/// trusts stays unguarded.
fn ts_link_unlink(link: *mut u32) {
    // SAFETY: caller passes the live 8-byte TSLink pair; next-field dword.
    let next = unsafe { link.read_unaligned() };
    if next == 0 {
        return;
    }
    // SAFETY: prev-field dword of the same live pair.
    let p_prev = unsafe { link.add(1) };
    // SAFETY: in-bounds field of the same live pair.
    let prev = unsafe { p_prev.read_unaligned() };
    let slot = if prev & 1 == 0 && prev != 0 {
        // SAFETY: successor's prev-anchor dword at next+4 (stock trusts it).
        let anchor = unsafe { ((next as usize).wrapping_add(4) as *const u32).read_unaligned() };
        (link as usize)
            .wrapping_add(prev as usize)
            .wrapping_sub(anchor as usize) as *mut u32
    } else {
        (prev & !1) as usize as *mut u32
    };
    // SAFETY: predecessor's forward slot re-pointed at our successor
    // (stock writes unguarded — a null/garbage slot faults like stock).
    unsafe { slot.write_unaligned(next) };
    // SAFETY: successor's prev-anchor takes our prev encoding.
    unsafe { ((next as usize).wrapping_add(4) as *mut u32).write_unaligned(prev) };
    // SAFETY: clear our next field.
    unsafe { link.write_unaligned(0) };
    // SAFETY: clear our prev field.
    unsafe { p_prev.write_unaligned(0) };
}

