    // guard hi (0x7ffab0), cell scale (0x810ae4), FISTP bias (0x86aa2c).
    const OFS: *const f32 = (BASE + 0x3f_fab4) as *const f32;
    const LO: *const f32 = (BASE + 0x3f_fd74) as *const f32;
    const HI: *const f32 = (BASE + 0x3f_fab0) as *const f32;
    const SCALE: *const f32 = (BASE + 0x41_0ae4) as *const f32;
    const BIAS: *const f32 = (BASE + 0x46_aa2c) as *const f32;

