    // SAFETY: as above.
    unsafe { COUNTER_A.write(c.wrapping_add(1)) };
    // SAFETY: as above, the second counter.
    let c = unsafe { COUNTER_B.read() };
    // SAFETY: as above.
    unsafe { COUNTER_B.write(c.wrapping_add(1)) };

