    let b0 = unsafe { box_ptr.read_unaligned() };
    // SAFETY: as above.
    let b1 = unsafe { box_ptr.wrapping_add(1).read_unaligned() };
    // SAFETY: as above.
    let b3 = unsafe { box_ptr.wrapping_add(3).read_unaligned() };
    // SAFETY: as above.
    let b4 = unsafe { box_ptr.wrapping_add(4).read_unaligned() };
