    let scale = unsafe { SCALE.read() };
    // SAFETY: as above.
    let bias = unsafe { BIAS.read() };
    let c1 = crate::math::world::collect_cell_index__6aa8b0(v1, scale, bias);
    let c0 = crate::math::world::collect_cell_index__6aa8b0(v0, scale, bias);
    let c4 = crate::math::world::collect_cell_index__6aa8b0(v4, scale, bias);
    let c3 = crate::math::world::collect_cell_index__6aa8b0(v3, scale, bias);
